<script setup>
import { useRouter } from 'vue-router'
const router = useRouter()
const currentIndex = 1 // вторая точка активна (0-based)
 
const routes = [
  '/onboarding/1',
  '/onboarding/2',
  '/onboarding/3',
  '/onboarding/4',
]
 
const goTo = (route) => {
  router.push(route)
}
 
const goNext = () => { router.push('/onboarding/4') }
